package me.xjanua.aitranswatch.controller;
import java.util.UUID; import org.springframework.data.domain.*; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import jakarta.validation.Valid; import me.xjanua.aitranswatch.dto.RestResponse; import me.xjanua.aitranswatch.dto.vehicle.*; import me.xjanua.aitranswatch.enums.VehicleStatus; import me.xjanua.aitranswatch.service.VehicleService;
@RestController @RequestMapping("/api/vehicles") public class VehicleController { private final VehicleService service; public VehicleController(VehicleService service){this.service=service;} @GetMapping public RestResponse<Page<VehicleResponse>> list(@RequestParam(required=false)String search,@RequestParam(required=false)VehicleStatus status,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return RestResponse.success(service.list(search,status,PageRequest.of(page,Math.min(Math.max(size,1),100),Sort.by("licensePlate").ascending())));}@GetMapping("/{id}")public RestResponse<VehicleResponse> get(@PathVariable UUID id){return RestResponse.success(service.get(id));}@PostMapping @PreAuthorize("hasAnyRole('ADMIN','DISPATCHER')") public ResponseEntity<RestResponse<VehicleResponse>> create(@Valid @RequestBody VehicleRequest request){return ResponseEntity.status(HttpStatus.CREATED).body(RestResponse.success(service.create(request)));}@PutMapping("/{id}") @PreAuthorize("hasAnyRole('ADMIN','DISPATCHER')")public RestResponse<VehicleResponse> update(@PathVariable UUID id,@Valid @RequestBody VehicleRequest request){return RestResponse.success(service.update(id,request));}@DeleteMapping("/{id}") @PreAuthorize("hasAnyRole('ADMIN','DISPATCHER')")public ResponseEntity<Void> deactivate(@PathVariable UUID id){service.deactivate(id);return ResponseEntity.noContent().build();}}
